// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 t1, uint256 t2, uint256 t3) public {
        t1 = bound(t1, 2, 1e12);
        t2 = bound(t2, t1 + 1, t1 + 1e6);
        vm.assume(t3 > t2 && t3 <= t1 + t2 && t3 <= type(uint256).max);

        vm.warp(t1);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        vm.warp(t2);
        (bool ok2,) = address(c).call{value: 10 ether}("");
        assertTrue(ok2);

        vm.warp(t3);
        (bool ok3,) = address(c).call{value: 10 ether}("");
        assertTrue(ok3);
    }
}
